package com.lqq.supportflow.conversation.api;
import com.lqq.supportflow.conversation.application.SubmitCustomerMessageService; import com.lqq.supportflow.conversation.domain.Generation; import com.lqq.supportflow.shared.AuthenticatedPrincipal; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/customer/conversations/{conversationId}/messages") public class CustomerMessageController { private final SubmitCustomerMessageService service; public CustomerMessageController(SubmitCustomerMessageService service){this.service=service;} @PostMapping ResponseEntity<Generation> submit(@AuthenticationPrincipal AuthenticatedPrincipal principal,@PathVariable Long conversationId,@RequestHeader("Idempotency-Key") String idempotencyKey,@Valid @RequestBody SubmitMessageRequest request){return ResponseEntity.status(HttpStatus.ACCEPTED).body(service.submit(principal.tenantId(),principal.userId(),conversationId,request.content(),idempotencyKey));}}
